<script setup>
import {ref,onMounted} from 'vue';import {doctorService} from '../../../services/doctors';import {useDoctorStore} from '../../../stores/doctors';import FormErrors from '../../../components/ui/FormErrors.vue';const store=useDoctorStore(),result=ref(null),error=ref(null),busy=ref(false);const labels={'doctor.created':'Doctor created','doctor.updated':'Doctor updated','doctor.activated':'Doctor activated','doctor.deactivated':'Doctor deactivated','doctor.schedule.updated':'Schedule updated','doctor.leave.created':'Leave added','doctor.leave.cancelled':'Leave cancelled','doctor.branch.assigned':'Branches assigned'};
async function load(page=1){busy.value=true;error.value=null;try{result.value=(await doctorService.activity(store.doctor.id,page)).data.data;}catch(e){error.value=e;}finally{busy.value=false;}}onMounted(()=>load());
</script>
<template><section class="clinic-panel"><h2 class="text-lg font-bold">Clinician activity</h2><FormErrors :error="error"/><button v-if="error" class="btn mt-4" @click="load()">Try again</button><p v-if="busy" class="empty-state">Loading activity...</p><template v-else-if="result"><div v-for="item in result.data" :key="item.id" class="patient-document-row"><strong>{{labels[item.action]||'Clinician record changed'}}</strong><span class="text-sm text-slate-500">{{item.actor_name}} · {{new Date(item.created_at).toLocaleString()}}</span></div><p v-if="!result.data.length" class="empty-state">No activity recorded.</p><div v-if="result.last_page>1" class="patient-pagination"><button :disabled="result.current_page===1" @click="load(result.current_page-1)">Previous</button><span>{{result.current_page}} / {{result.last_page}}</span><button :disabled="result.current_page===result.last_page" @click="load(result.current_page+1)">Next</button></div></template></section></template>
